from queue import Queue
import copy
from dateutil.parser import isoparse
from splunk.pdf.pdfgen_search import InlineSearchManager, SavedSearchManager, PostProcessSearchManager
from splunk.pdf.studio.o11y_manager import O11yDataManager
import splunk.pdf.pdfgen_utils as pdfgen_utils
from splunk.pdf.studio.namespace import get_spl2_module_metadata, generate_spl2_view_query
logger = pdfgen_utils.getLogger()


def create_search_queue(all_searches):
    """
    build and return the search queue after removing duplicates
    """
    search_queue = Queue()
    duplicate_data_sources = {}

    deduped_searches = group_searches_by_search_cache_key(all_searches)

    for search in deduped_searches:
        search_queue.put(
            (search["search_manager"], search["ds"], search["data_source"], search["max_results_to_fetch"])
        )
        if search["duplicate_ds_ids"]:
            duplicate_data_sources[search["ds"]] = search["duplicate_ds_ids"]

    return search_queue, duplicate_data_sources


def group_searches_by_search_cache_key(searches_dict: dict) -> list:
    """
    groups searches by their searchKey. Use the one with the largest maxResults
    as original and include others as duplicates
    """
    grouped_searches = {}

    for ds in searches_dict:
        cache_key, max_results, search_manager, data_source = searches_dict[ds]

        # search already exists
        if cache_key is not None and cache_key in grouped_searches:
            existing = grouped_searches[cache_key]
            # bigger one already exists, this is a duplicate
            if existing["max_results_to_fetch"] > max_results:
                existing["duplicate_ds_ids"].append(ds)
            else:
                # this is the bigger one, update the existing record
                existing["max_results_to_fetch"] = max_results
                existing["search_manager"] = search_manager
                existing["data_source"] = data_source
                existing["duplicate_ds_ids"].append(existing["ds"])
                existing["ds"] = ds
            continue

        # search does not exist. Create entry for it
        grouped_searches[cache_key] = {
            "max_results_to_fetch": max_results,
            "search_manager": search_manager,
            "data_source": data_source,
            "ds": ds,
            "duplicate_ds_ids": [],
        }

    return list(grouped_searches.values())


def clone_duplicate_data_sources(duplicate_data_sources, resolved_data_sources, data_sources) -> None:
    """
    iterates over the duplicate data sources and copies them into the resolved_data_sources
    """
    for ds in duplicate_data_sources:
        if ds not in resolved_data_sources:
            continue

        for duplicate_data_source_id in duplicate_data_sources[ds]:
            original_definition = data_sources[duplicate_data_source_id]
            cloned = copy.deepcopy(resolved_data_sources[ds])
            cloned_definition = cloned["definition"]
            if "options" not in cloned_definition:
                cloned_definition["options"] = {}

            if "meta" not in cloned_definition["options"]:
                cloned_definition["options"]["meta"] = {}

            # retain the original definition
            cloned_definition["options"]["meta"]["originalDefinition"] = original_definition
            if "name" in original_definition:
                # smart source tokens have the name built-in, replace this with the duplicate name
                updated_tokens = {}
                for token in cloned["smartSourceTokens"]:
                    updated_tokens[
                        token.replace(f"{cloned_definition['name']}:", f"{original_definition['name']}:")
                    ] = cloned["smartSourceTokens"][token]
                cloned["smartSourceTokens"] = updated_tokens

                # keep the original name
                cloned_definition["name"] = original_definition["name"]

            # Add the cloned data source into the resolved dict
            resolved_data_sources[duplicate_data_source_id] = cloned

def get_epoch_time_from_iso(time):
    """
    If time is valid iso format, return the epoch time. Otherwise return time unchanged
    """
    try:
        return isoparse(time).timestamp()
    except Exception:
        return time

def get_search_manager(data_source_name, data_sources, manager_map, namespace, owner, session_key) -> dict:
    """
    Return the search manager for the corresponding dataSourceName if it already exists in the managerMap. Otherwise,
    create and return a search manager based on the type of dataSource, or None if there is an error.
    Add the search manager to the managerMap.
    """
    if data_source_name in manager_map:
        return manager_map[data_source_name]

    cache_key = None
    search_manager = None
    data_source = data_sources.get(data_source_name, {})
    options = data_source.get("options", {})
    data_source_type = data_source.get("type")

    if data_source_type == "ds.search":
        query = options.get("query")
        if query is not None:
            earliest = options.get("queryParameters", {}).get("earliest")
            latest = options.get("queryParameters", {}).get("latest")
            cache_key = query + str(earliest) + str(latest)
            search_manager = InlineSearchManager(query, earliest, latest, namespace, owner, session_key)
    elif data_source_type == "ds.savedSearch":
        name = options.get("ref")
        if name is not None:
            app = options.get("app", namespace)
            use_saved_time_range = options.get("useSavedTimeRange", True)
            if use_saved_time_range == False:
                earliest = options.get("queryParameters", {}).get("earliest", None)
                earliest = get_epoch_time_from_iso(earliest)
                latest = options.get("queryParameters", {}).get("latest", None)
                latest = get_epoch_time_from_iso(latest)
            else:
                earliest = None
                latest = None
            cache_key = name + app + str(use_saved_time_range) + str(earliest) + str(latest)
            search_manager = SavedSearchManager(
                name, earliestTime=earliest, latestTime=latest, namespace=app, owner=owner, sessionKey=session_key, forceScheduledTimeRange=True
            )
    elif data_source_type == "ds.chain":
        query = options.get("query")
        parent_data_source_name = options.get("extend")
        if query is not None and parent_data_source_name is not None:
            cache_key = query + parent_data_source_name
            parent_search = get_search_manager(
                parent_data_source_name, data_sources, manager_map, namespace, owner, session_key
            )
            if parent_search["search_manager"] is not None:
                search_manager = PostProcessSearchManager(
                    query, parent_search["search_manager"], namespace, owner, session_key
                )
    elif data_source_type == "ds.o11y":
        search_manager = O11yDataManager(data_source, owner, session_key)
    elif data_source_type == "ds.spl2":
        query = options.get("query")
        if query is not None:
            spl2_query = add_leading_spl2_annotation(query)
            earliest = options.get("queryParameters", {}).get("earliest")
            latest = options.get("queryParameters", {}).get("latest")
            cache_key = spl2_query + str(earliest) + str(latest)
            search_manager = InlineSearchManager(spl2_query, earliest, latest, namespace, owner, session_key)
    elif data_source_type == "ds.spl2.view":
        view = options.get("view")
        ds_namespace = options.get("namespace")
        if view is not None and ds_namespace is not None:
            spl2_query = generate_spl2_view_query(view, ds_namespace)
            use_saved_time_range = options.get("useSavedTimeRange", True)
            if use_saved_time_range == False:
                earliest = options.get("queryParameters", {}).get("earliest")
                latest = options.get("queryParameters", {}).get("latest")
            else:
                view_metadata = get_spl2_module_metadata(ds_namespace, session_key)
                earliest = view_metadata.get("earliestTime")
                latest = view_metadata.get("latestTime")
            cache_key = spl2_query + str(use_saved_time_range) + str(earliest) + str(latest)
            search_manager = InlineSearchManager(spl2_query, earliest, latest, namespace, owner, session_key)

    if search_manager is None:
        logger.error("Unable to create search manager for dataSource %s." % data_source_name)

    search = {"search_manager": search_manager, "cache_key": cache_key}
    manager_map[data_source_name] = search
    return search

def starts_with_spl2_annotation(query: str):
    trimmed_query = query.strip()
    query_without_leading_pipe = trimmed_query[1:].strip() if trimmed_query.startswith('|') else trimmed_query
    return query_without_leading_pipe.startswith('@spl2')

def add_leading_spl2_annotation(query: str):
    trimmed_query = query.strip()
    if starts_with_spl2_annotation(trimmed_query):
        if trimmed_query.startswith('|'):
            return trimmed_query
        return f"| {trimmed_query}"
    return f"| @spl2 {trimmed_query}"